"use client";

import { useEffect, useRef } from "react";
import { motion, useInView, useMotionValue, useReducedMotion, useSpring, useTransform } from "framer-motion";

function Price({ to }: { to: number }) {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-10% 0px" });
  const shouldReduceMotion = useReducedMotion();
  const motionValue = useMotionValue(shouldReduceMotion ? to : 0);
  const spring = useSpring(motionValue, { stiffness: 90, damping: 20 });
  const display = useTransform(spring, (v) => Math.round(v));

  useEffect(() => {
    if (isInView && !shouldReduceMotion) motionValue.set(to);
  }, [isInView, to, motionValue, shouldReduceMotion]);

  return <motion.span ref={ref}>{display}</motion.span>;
}

export function PricingCard({
  name,
  price,
  features,
  popular = false,
}: {
  name: string;
  price: number;
  features: string[];
  popular?: boolean;
}) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.div
      whileHover={shouldReduceMotion ? undefined : { y: -4 }}
      transition={{ type: "spring", stiffness: 380, damping: 28 }}
      className={`group relative w-full max-w-[280px] overflow-hidden rounded-2xl border p-6 dark:bg-neutral-950 ${
        popular
          ? "border-emerald-400/60 bg-white shadow-[0_20px_40px_-24px_rgba(5,150,105,0.4)] dark:border-emerald-400/40"
          : "border-slate-200 bg-white dark:border-slate-700"
      }`}
    >
      {popular && (
        <span
          aria-hidden
          className="pointer-events-none absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-emerald-400/10 to-transparent transition-transform duration-[1400ms] ease-out group-hover:translate-x-full motion-reduce:hidden"
        />
      )}
      {popular && (
        <span className="inline-flex items-center rounded-full bg-emerald-700 px-2.5 py-0.5 text-[11px] font-semibold text-white">
          Most popular
        </span>
      )}
      <h3 className={`text-base font-semibold text-slate-900 dark:text-white ${popular ? "mt-4" : ""}`}>{name}</h3>
      <div className="mt-1 flex items-baseline gap-1">
        <span className="text-4xl font-semibold tabular-nums text-slate-900 dark:text-white">
          $<Price to={price} />
        </span>
        <span className="text-sm text-slate-400 dark:text-slate-500">/ month</span>
      </div>

      <ul className="mt-5 flex flex-col gap-2.5">
        {features.map((feature, i) => (
          <motion.li
            key={feature}
            initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0, x: -6 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true, margin: "-10% 0px" }}
            transition={{ delay: shouldReduceMotion ? 0 : 0.15 + i * 0.07, duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
            className="flex items-center gap-2 text-sm text-slate-600 dark:text-slate-300"
          >
            <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden className="shrink-0 text-emerald-600">
              <path d="M3 8.5l3 3 7-7.5" />
            </svg>
            {feature}
          </motion.li>
        ))}
      </ul>

      <motion.button
        whileHover={shouldReduceMotion ? undefined : { y: -2 }}
        whileTap={{ scale: 0.96, y: 0 }}
        transition={{ type: "spring", stiffness: 500, damping: 30 }}
        className={`mt-6 w-full rounded-lg px-4 py-2.5 text-sm font-medium transition-[box-shadow,background-color] duration-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 ${
          popular
            ? "bg-emerald-700 text-white shadow-[0_1px_2px_rgba(5,150,105,0.3)] hover:bg-emerald-600 hover:shadow-[0_12px_24px_-8px_rgba(5,150,105,0.65)] focus-visible:outline-emerald-700"
            : "border border-slate-300 text-slate-700 hover:border-slate-400 focus-visible:outline-slate-400 dark:border-slate-600 dark:text-slate-200"
        }`}
      >
        Choose {name}
      </motion.button>
    </motion.div>
  );
}
